return {["scripts/items/bottle_of_frontier_soda.lua"]={["Path"]="scripts/items/bottle_of_frontier_soda.lua",["SHA256"]="5fcbfbe854074266700778961cf093f287e5ff09aaf6697510e69a6b4a531362",["Text"]="-----------------------------------\n-- ID: 5944\n-- Item: Bottle of Frontier Soda\n-- Item Effect: Restores 20 TP over 60 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.REGAIN) then\n        target:addStatusEffect(xi.effect.REGAIN, { power = 1, duration = 60, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_giants_drink.lua"]={["Path"]="scripts/items/bottle_of_giants_drink.lua",["SHA256"]="d8e9033c31b50a71f9d5596bb9b2e10a279b37206cc34f484d27c8e25a51e9ef",["Text"]="-----------------------------------\n-- ID: 4172\n-- Item: Reraiser\n-- Item Effect: +100% HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 900\n    target:delStatusEffect(xi.effect.MAX_HP_BOOST)\n    target:addStatusEffect(xi.effect.MAX_HP_BOOST, { power = 100, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_gnostics_drink.lua"]={["Path"]="scripts/items/bottle_of_gnostics_drink.lua",["SHA256"]="b92e62fe546883cbe3408d1c9872fcef0a31362992015977a46eff607b0fb811",["Text"]="-----------------------------------\n-- ID: 5394\n-- Item: bottle_of_gnostics_drink\n-- Item Effect: Enmity -\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.PAX\n    local power     = -10   -- Power Level unknown, using Animus Minueo Value as baseline.\n    local duration  = 60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_goblin_drink.lua"]={["Path"]="scripts/items/bottle_of_goblin_drink.lua",["SHA256"]="0de996ad175f92f02fe9e4e53efc3776ab670c39de79891cc885521a018c11a0",["Text"]="-----------------------------------\n-- ID: 4541\n-- Item: Goblin Drink\n-- Item Effect: Restores 1 MP while healing / 3 tick 180 mins.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.FOOD) then\n        target:addStatusEffect(xi.effect.FOOD, { power = 1, duration = 10800, origin = user, tick = 3, subType = 4541 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\nend\n\nitemObject.onEffectTick = function(target, effect)\n    if target:hasStatusEffect(xi.effect.HEALING) then\n        target:addMP(effect:getPower())\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_grape_juice.lua"]={["Path"]="scripts/items/bottle_of_grape_juice.lua",["SHA256"]="e55207a7131a273d90ee7e413c0a599ecae75aa7597f67844502266661064b57",["Text"]="-----------------------------------\n-- ID: 4441\n-- Item: Grape Juice\n-- Item Effect: Restores 60 MP over 90 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 2, duration = 90, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_hallowed_water.lua"]={["Path"]="scripts/items/bottle_of_hallowed_water.lua",["SHA256"]="9a35e7c0619a60cbc3b141a8cab5bafcd9a2988f6d05f0d83bf94816ab71a046",["Text"]="-----------------------------------\n-- ID: 5306\n-- Item: Bottle of Hallowed Water\n-- Item Effect: Removes curse. Better chance to remove doom.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local curse = target:getStatusEffect(xi.effect.CURSE_I)\n    local curse2 = target:getStatusEffect(xi.effect.CURSE_II)\n    local bane = target:getStatusEffect(xi.effect.BANE)\n    local power = 33 + target:getMod(xi.mod.ENHANCES_HOLYWATER)\n\n    if\n        target:hasStatusEffect(xi.effect.DOOM) and\n        power > math.randomInt(1, 100)\n    then\n        target:delStatusEffect(xi.effect.DOOM)\n        target:messageBasic(xi.msg.basic.NARROWLY_ESCAPE)\n    elseif curse ~= nil and curse2 ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n        target:delStatusEffect(xi.effect.CURSE_II)\n        target:delStatusEffect(xi.effect.BANE)\n    elseif curse ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n        target:delStatusEffect(xi.effect.BANE)\n    elseif curse2 ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_II)\n        target:delStatusEffect(xi.effect.BANE)\n    elseif curse ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n    elseif curse2 ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_II)\n    elseif bane ~= nil then\n        target:delStatusEffect(xi.effect.BANE)\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_hi-ether_drops.lua"]={["Path"]="scripts/items/bottle_of_hi-ether_drops.lua",["SHA256"]="4ac3daf885ce5d4e7cec48caf9ff0bb9a70e98a8b5f520942dc87449f8c4e9aa",["Text"]="-----------------------------------\n-- ID: 5358\n-- Item: Hi-Ether Drop\n-- Item Effect: Restores 45 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addMP(45 * xi.settings.main.ITEM_POWER)\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 300, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_hi-potion_drops.lua"]={["Path"]="scripts/items/bottle_of_hi-potion_drops.lua",["SHA256"]="a05c79a752501b9886b84b0d0ce92db6fb22aebe22c33210093f860b859cc670",["Text"]="-----------------------------------\n-- ID: 5328\n-- Item: Hi-Potion Drop\n-- Item Effect: Restores 110 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addHP(110 * xi.settings.main.ITEM_POWER)\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 300, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_hysteroanima.lua"]={["Path"]="scripts/items/bottle_of_hysteroanima.lua",["SHA256"]="65ffcd2dce35063b4df0ef0ce1ccbcbf1bc3d23c86fca982501dda4fc19de626",["Text"]="-----------------------------------\n-- ID: 5262\n-- Item: Bottle Of Hysteroanima\n-- Item Effect: HYSTERIA\n-- TODO: The mobskill actually finishes but with no animation,\n--       and the category changes to 7 instead of 11 (mobskill finish)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:getEcosystem() ~= xi.ecosystem.EMPTY then -- Empty\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:checkDistance(caster) > 10 then\n        result = xi.msg.basic.TOO_FAR_AWAY\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, player)\n    target:delStatusEffectSilent(xi.effect.HYSTERIA)\n    target:addStatusEffect(xi.effect.HYSTERIA, { power = 1, duration = math.randomInt(25, 32), origin = player, flag = xi.effectFlag.NO_LOSS_MESSAGE })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_kitron_juice.lua"]={["Path"]="scripts/items/bottle_of_kitron_juice.lua",["SHA256"]="1e17b4a2345d17fa2ba51cce1564a7d0200964b57672aab44a3821e762e6d65b",["Text"]="-----------------------------------\n-- ID: 5932\n-- Item: Bottle of Kitron Juice\n-- Item Effect: Restores 180 MP over 180 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 3, duration = 180, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_mana_boost.lua"]={["Path"]="scripts/items/bottle_of_mana_boost.lua",["SHA256"]="59f155f627af0b84ad21110e3c33de06941e6b70b973ada79c1780cc9701f2ed",["Text"]="-----------------------------------\n-- ID: 4172\n-- Item: Reraiser\n-- Item Effect: +50% HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 900\n    target:delStatusEffect(xi.effect.MAX_MP_BOOST)\n    target:addStatusEffect(xi.effect.MAX_MP_BOOST, { power = 50, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_melon_juice.lua"]={["Path"]="scripts/items/bottle_of_melon_juice.lua",["SHA256"]="bb36b92afeebdaf2df2dafe8aff4adc063ad8e58cb49b5f9a04965018ca73e96",["Text"]="-----------------------------------\n-- ID: 4424\n-- Item: Melon Juice\n-- Item Effect: Restores 90 MP over 135 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 2, duration = 135, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_monarchs_drink.lua"]={["Path"]="scripts/items/bottle_of_monarchs_drink.lua",["SHA256"]="6d8b8e9decd39c6309c1620e11be2f8affb4459965a50efe140b29e74db50a12",["Text"]="-----------------------------------\n-- ID: 5393\n-- Item: bottle_of_monarchs_drink\n-- Item Effect: Regain\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.REGAIN\n    local power     = 3\n    local duration  = 180\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_movalpolos_water.lua"]={["Path"]="scripts/items/bottle_of_movalpolos_water.lua",["SHA256"]="48fcdc78835c4166274ebe0be4661b1d00f80d71fc425f3557ab4fa6ad30dd0b",["Text"]="-----------------------------------\n-- ID: 5165\n-- Item: Bottle of Movalpolos Water\n-- Item Effect: Food Effect with no obvious effects.\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\n-- Previously, this item used to give a 2/tick refresh effect (not food effect with refresh) if used on lightsday.\n-- That was proven wrong simply by using a movalpolos water on lightsday. It gives a food effect just like JP wiki claims\n-- https://wiki.ffo.jp/html/1657.html\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 30 * 60, origin = user, subType = 5165 })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_mulsum.lua"]={["Path"]="scripts/items/bottle_of_mulsum.lua",["SHA256"]="4670d144adbb2e46b58d6ca6426c0083a561fa7397b0a6afe89c2f5cd3b8c3f3",["Text"]="-----------------------------------\n-- ID: 4128\n-- Item: Ether\n-- Item Effect: Restores 10 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, target:addMP(10 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_orange_juice.lua"]={["Path"]="scripts/items/bottle_of_orange_juice.lua",["SHA256"]="f954c21f878d0c1aba48dee824fb024468a18a7d8a1f20ccde38171621eff562",["Text"]="-----------------------------------\n-- ID: 4422\n-- Item: Orange Juice\n-- Item Effect: Restores 30 MP over 1 minute and 30 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n    local legsEquipped  = target:getEquipID(xi.slot.LEGS)\n    local refreshPower  = (legsEquipped == xi.item.DREAM_TROUSERS_P1 or legsEquipped == xi.item.DREAM_PANTS_P1) and 2 or 1\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = refreshPower, duration = 90, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_pineapple_juice.lua"]={["Path"]="scripts/items/bottle_of_pineapple_juice.lua",["SHA256"]="09acf0befc6831f1e42389ad53a9ea09de1627e35832d4eff4da2bf3800fa1ec",["Text"]="-----------------------------------\n-- ID: 4442\n-- Item: Pineapple Juice\n-- Item Effect: Restores 80 MP over 240 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 1, duration = 240, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_potion_drops.lua"]={["Path"]="scripts/items/bottle_of_potion_drops.lua",["SHA256"]="1da9c1e578f5aec551b6800ecb3ac9433edac9341bdd18eedb43f0aeb57734b9",["Text"]="-----------------------------------\n-- ID: 5327\n-- Item: Potion Drop\n-- Item Effect: Restores 60 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addHP(60 * xi.settings.main.ITEM_POWER)\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 300, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_psychoanima.lua"]={["Path"]="scripts/items/bottle_of_psychoanima.lua",["SHA256"]="c6c9f173c33d34a85cf60525cfd6f9118a8ed1d7ef05293f8fc3c17998049854",["Text"]="-----------------------------------\n-- ID: 5261\n-- Item: Bottle Of Psychoanima\n-- Item Effect: Intimidate\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:getEcosystem() ~= xi.ecosystem.EMPTY then -- Empty\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:checkDistance(caster) > 10 then\n        result = xi.msg.basic.TOO_FAR_AWAY\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, player)\n    target:delStatusEffectSilent(xi.effect.INTIMIDATE)\n    target:addStatusEffect(xi.effect.INTIMIDATE, { power = 100, duration = math.randomInt(25, 32), origin = player })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_sprinters_drink.lua"]={["Path"]="scripts/items/bottle_of_sprinters_drink.lua",["SHA256"]="bd9492598e63ffbf5dad12de367868fac6a5ea8049e7b07f0b145d5ff0175389",["Text"]="-----------------------------------\n-- ID: 5397\n-- Item: bottle_of_sprinters_drink\n-- Item Effect: Grants Flee for 60s\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect = xi.effect.FLEE\n    local power = 7500\n    local duration = 60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_spys_drink.lua"]={["Path"]="scripts/items/bottle_of_spys_drink.lua",["SHA256"]="44aa53afdc33783bc23d205ba7b39591394bec1cb2731fb721efcdecb19c3e36",["Text"]="-----------------------------------\n-- ID: 5389\n-- Item: bottle_of_spys_drink\n-- Item Effect: Haste +30%\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect   = xi.effect.HASTE\n    local power    = 3000\n    local duration = 90\n\n    if not target:hasStatusEffect(xi.effect.HASTE) then\n        xi.itemUtils.addItemEffect(target, effect, power, duration)\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_stalwarts_gambir.lua"]={["Path"]="scripts/items/bottle_of_stalwarts_gambir.lua",["SHA256"]="eea446cc8a44c1727a9ccf153e90d49ba0e7c0e699917fae3db7883b7bc9c3bb",["Text"]="-----------------------------------\n-- ID: 5840\n-- Item: bottle_of_stalwarts_gambir\n-- Item Effect: ACC 100 RACC 100 RATTP 50 ATTP 50\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect1   = xi.effect.ACCURACY_BOOST\n    local effect2   = xi.effect.ATTACK_BOOST\n    local power1    = 100 --ACC/RACC\n    local power2    =  50 --ATTP/RATTP\n    local duration  = 300\n\n    xi.itemUtils.addTwoItemEffects(target, effect1, effect2, power1, power2, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_stalwarts_tonic.lua"]={["Path"]="scripts/items/bottle_of_stalwarts_tonic.lua",["SHA256"]="c2d70895200fdfcd1332c7803a5256ca6e6db71eef9507c59727aeb9da07454d",["Text"]="-----------------------------------\n-- ID: 5839\n-- Item: bottle_of_stalwarts_tonic\n-- Item Effect: ACC 50 RACC 50 RATTP 25 ATTP 25\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect1   = xi.effect.ACCURACY_BOOST\n    local effect2   = xi.effect.ATTACK_BOOST\n    local power1    =  50 --ACC/RACC\n    local power2    =  25 --ATTP/RATTP\n    local duration  = 300\n\n    xi.itemUtils.addTwoItemEffects(target, effect1, effect2, power1, power2, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_strange_juice.lua"]={["Path"]="scripts/items/bottle_of_strange_juice.lua",["SHA256"]="43e4d56caad9ba92ed97da564a45e35428bf7ea5848bb0799f64925549eb9554",["Text"]="-----------------------------------\n-- ID: 5438\n-- Item: Bottle of Strange Juice\n-- Item Effect: Restores 200 MP over 300 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 2, duration = 300, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_swiftshot_drink.lua"]={["Path"]="scripts/items/bottle_of_swiftshot_drink.lua",["SHA256"]="d931e607a3648278b510f9b9d8b80a5595ba3a5c8f1514a76d8384b8d9d82ed3",["Text"]="-----------------------------------\n-- ID: 5850\n-- Item: bottle_of_swiftshot_drink\n-- Item Effect: Double Shot +100\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.MULTI_SHOTS\n    local power     = 100 --Double Shot Rate\n    local duration  =  60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_swiftshot_tonic.lua"]={["Path"]="scripts/items/bottle_of_swiftshot_tonic.lua",["SHA256"]="12f625770a73fb398542bcb37467f5644260aedb2ddfd4bad0b27e84a035d95e",["Text"]="-----------------------------------\n-- ID: 5852\n-- Item: bottle_of_swiftshot_tonic\n-- Item Effect: Double Shot +50\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.MULTI_SHOTS\n    local power     = 50 --Double Shot Rate\n    local duration  = 60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_terroanima.lua"]={["Path"]="scripts/items/bottle_of_terroanima.lua",["SHA256"]="c0db65c4262f865fa8dd86f6696b18816651c4415a915401d454bd2d33c32226",["Text"]="-----------------------------------\n-- ID: 5263\n-- Item: Bottle Of Terroanima\n-- Item Effect: Terror\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if\n        target:getEcosystem() ~= xi.ecosystem.EMPTY and\n        caster:getZone():getRegionID() == xi.region.PROMYVION\n    then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:checkDistance(caster) > 10 then\n        result = xi.msg.basic.TOO_FAR_AWAY\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, player)\n    local duration = math.randomInt(25, 32) -- Random duration between 25s and 32s\n    target:setLocalVar('EmptyTerror', GetSystemTime()) -- Sets terror start time.\n    target:setLocalVar('EmptyTerrorDuration', duration) -- Sets terror duration.\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_tomato_juice.lua"]={["Path"]="scripts/items/bottle_of_tomato_juice.lua",["SHA256"]="b6174aa4b6e1f7c1ea1afaf7b3934db2ab75883b0c37f5469fe8848d623213b1",["Text"]="-----------------------------------\n-- ID: 4425\n-- Item: Tomato Juice\n-- Item Effect: Restores 60 MP over 180 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 1, duration = 180, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_vampire_juice.lua"]={["Path"]="scripts/items/bottle_of_vampire_juice.lua",["SHA256"]="9f51b8795001a37a215d1c96f6e080887e26e9c95765c69f37ce1bebeefd8a09",["Text"]="-----------------------------------\n-- ID: 4512\n-- Item: Vampire Juice\n-- Item Effect: Restores 60 HP and MP over 90 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect     = target:getStatusEffect(xi.effect.REGEN)\n    local refreshEffect   = target:getStatusEffect(xi.effect.REFRESH)\n    local canApplyRegen   = not regenEffect or regenEffect:getTier() == 0\n    local canApplyRefresh = not refreshEffect or refreshEffect:getTier() == 0\n\n    if canApplyRegen then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 2, duration = 90, origin = user, tick = 3 })\n    end\n\n    if canApplyRefresh then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 2, duration = 90, origin = user, tick = 3 })\n    end\n\n    if\n        not canApplyRegen and\n        not canApplyRefresh\n    then\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when both Regen and Refresh are protected by tiered spell effects.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_vicars_drink.lua"]={["Path"]="scripts/items/bottle_of_vicars_drink.lua",["SHA256"]="3dc9dafe875bf4e32a6cf427d9cdc38187f2801dc856e6136baed909cfd8ca78",["Text"]="-----------------------------------\n-- ID: 5439\n-- Item: bottle_of_vicars_drink\n-- Item Effect: Instantly removes all negative status effects from target\n--              Does not remove Plague or Curse\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effects = xi.itemUtils.removableEffects\n    local count = 33\n\n    xi.itemUtils.removeMultipleEffects(target, effects, count)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_viper_potion.lua"]={["Path"]="scripts/items/bottle_of_viper_potion.lua",["SHA256"]="9a71300476d8c5aad63094a894c95becd9a91c5117d0ff1147f5ad4391b099cc",["Text"]="-----------------------------------\n-- ID: 4157\n-- Item: Viper Potion\n-- Item Effect: Removes 300 HP over 3 mins\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 5, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_wizards_drink.lua"]={["Path"]="scripts/items/bottle_of_wizards_drink.lua",["SHA256"]="d5c4462650fd7d053ad3f6819aa5e09a79c4e57380958b020f432a71de8918f1",["Text"]="-----------------------------------\n-- ID: 4172\n-- Item: Wizards Drink\n-- Item Effect: +100% MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 900\n    target:delStatusEffect(xi.effect.MAX_MP_BOOST)\n    target:addStatusEffect(xi.effect.MAX_MP_BOOST, { power = 100, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_yagudo_drink.lua"]={["Path"]="scripts/items/bottle_of_yagudo_drink.lua",["SHA256"]="036528268161df7a549c26844e49383e688fda5e73e29fedaa185f00e24c0a70",["Text"]="-----------------------------------\n-- ID: 4558\n-- Item: Yagudo Drink\n-- Item Effect: Restores 120 MP over 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 2, duration = 180, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_yellow_liquid.lua"]={["Path"]="scripts/items/bottle_of_yellow_liquid.lua",["SHA256"]="36a9e91192bdafa67bd1c92d4238ecc861c80d4984cd0402d4efdf35f296e923",["Text"]="-----------------------------------\n--  ID: 5264\n--  Item: Yellow Liquid\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    -- TODO: Can this ONLY be used on Mammet types?\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 30, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nreturn itemObject\n"},["scripts/items/boulder_box.lua"]={["Path"]="scripts/items/boulder_box.lua",["SHA256"]="a52440abed3a13d8408a4e1b7aea803ce6738d65a359871bce4203642881aa7c",["Text"]="-----------------------------------\n-- ID: 6185\n-- Boulder Box\n-- Breaks up a Boulder Box\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RIFTBORN_BOULDER, math.randomInt(15, 30) } })\nend\n\nreturn itemObject\n"},["scripts/items/boulder_case.lua"]={["Path"]="scripts/items/boulder_case.lua",["SHA256"]="5c59ceee19705b891efc1cc7ca6df3dd52adafd9b894c0b5057c9607f5db8377",["Text"]="-----------------------------------\n-- ID: 6182\n-- Boulder Case\n-- Breaks up a Boulder Case\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RIFTBORN_BOULDER, math.randomInt(3, 15) } })\nend\n\nreturn itemObject\n"},["scripts/items/bounty_list.lua"]={["Path"]="scripts/items/bounty_list.lua",["SHA256"]="4c0dd1863bc662601486e3969b29183a2e6d5ed6445f8a58a095df25aa492045",["Text"]="-----------------------------------\n-- ID: 6170\n-- Item: Bounty List\n-- A simple list of known criminals who are better off dead.\n-- Every single name is crossed out in Azima's handwriting.\n-- Adventurers note that reading it increases one's elemental magic skill.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.skillBookCheck(target, xi.skill.ELEMENTAL_MAGIC)\nend\n\nitemObject.onItemUse = function(target)\n    xi.itemUtils.skillBookUse(target, xi.skill.ELEMENTAL_MAGIC)\nend\n\nreturn itemObject\n"},["scripts/items/bowl_of_adamantoise_soup.lua"]={["Path"]="scripts/items/bowl_of_adamantoise_soup.lua",["SHA256"]="89a51df652b57707a58e90778977a3199df5a695f988a192936133b205fc6a0f",["Text"]="-----------------------------------\n-- ID: 5210\n-- Item: Bowl of Adamantoise Soup\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Strength -7\n-- Dexterity -7\n-- Agility -7\n-- Vitality -7\n-- Intelligence -7\n-- Mind -7\n-- Charisma -7\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -7)\n    effect:addMod(xi.mod.DEX, -7)\n    effect:addMod(xi.mod.AGI, -7)\n    effect:addMod(xi.mod.VIT, -7)\n    effect:addMod(xi.mod.INT, -7)\n    effect:addMod(xi.mod.MND, -7)\n    effect:addMod(xi.mod.CHR, -7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bowl_of_adoulinian_soup.lua"]={["Path"]="scripts/items/bowl_of_adoulinian_soup.lua",["SHA256"]="82e8b2330814a2aab78c89b8ce1a179f7a81713ebf711fb2be50052330623abf",["Text"]="-----------------------------------\n-- ID: 5998\n-- Item: Bowl of Adoulin Soup\n-- Food Effect: 180 Min, All Races\n-----------------------------------\n-- HP % 3 Cap 40\n-- Vitality 3\n-- Defense % 15 Cap 70\n-- HP Healing 6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 3)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 40)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_DEFP, 15)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 70)\n    effect:addMod(xi.mod.HPHEAL, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bowl_of_adoulinian_soup_+1.lua"]={["Path"]="scripts/items/bowl_of_adoulinian_soup_+1.lua",["SHA256"]="8f4e6d3e101180419082f4f5d828e072f81d1c3a0bc561105b0939bc2fb0d9ab",["Text"]="-----------------------------------\n-- ID: 5999\n-- Item: Bowl of Adoulin Soup +1\n-- Food Effect: 240 Min, All Races\n-----------------------------------\n-- HP % 4 Cap 45\n-- Vitality 4\n-- Defense % 16 Cap 75\n-- HP Healing 7\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 4)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 45)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FOOD_DEFP, 16)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 75)\n    effect:addMod(xi.mod.HPHEAL, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bowl_of_ambrosia.lua"]={["Path"]="scripts/items/bowl_of_ambrosia.lua",["SHA256"]="e71516ce9177d2b7c8e2c54da02e9613672927588ad9fe0b327cbddbdecaae2b",["Text"]="-----------------------------------\n-- ID: 4511\n-- Item: Bowl of Ambrosia\n-- Food Effect: 240Min, All Races\n-----------------------------------\n-- HP +7\n-- MP +7\n-- STR +7\n-- DEX +7\n-- VIT +7\n-- AGI +7\n-- INT +7\n-- MND +7\n-- CHR +7\n-- Accuracy +7\n-- Ranged Accuracy +7\n-- Attack +7\n-- Ranged Attack +7\n-- Evasion +7\n-- Defense +7\n-- HP recovered while healing +7\n-- MP recovered while healing +7\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 7)\n    effect:addMod(xi.mod.FOOD_MP, 7)\n    effect:addMod(xi.mod.STR, 7)\n    effect:addMod(xi.mod.DEX, 7)\n    effect:addMod(xi.mod.VIT, 7)\n    effect:addMod(xi.mod.AGI, 7)\n    effect:addMod(xi.mod.INT, 7)\n    effect:addMod(xi.mod.MND, 7)\n    effect:addMod(xi.mod.CHR, 7)\n    effect:addMod(xi.mod.ATT, 7)\n    effect:addMod(xi.mod.RATT, 7)\n    effect:addMod(xi.mod.ACC, 7)\n    effect:addMod(xi.mod.RACC, 7)\n    effect:addMod(xi.mod.HPHEAL, 7)\n    effect:addMod(xi.mod.MPHEAL, 7)\n    effect:addMod(xi.mod.DEF, 7)\n    effect